create table if not exists public.expenses (
 id uuid primary key default gen_random_uuid(), activity_id uuid references public.activities(id) on delete set null, project_id uuid references public.projects(id) on delete set null, user_id uuid references public.profiles(id), category text not null, description text not null, amount numeric(14,2) not null check(amount >= 0), approved_amount numeric(14,2), approval_comments text, receipt_url text, expense_date date not null default current_date, status text not null default 'pending' check(status in ('draft','pending','under_review','approved','rejected','paid')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists idx_expenses_status on public.expenses(status); create index if not exists idx_expenses_project on public.expenses(project_id); create index if not exists idx_expenses_user on public.expenses(user_id); create index if not exists idx_expenses_date on public.expenses(expense_date desc);
alter table public.expenses enable row level security;
drop policy if exists expenses_select on public.expenses; create policy expenses_select on public.expenses for select to authenticated using (auth.uid() = user_id or public.get_my_role() in ('admin','gestor','financeiro'));
drop policy if exists expenses_insert on public.expenses; create policy expenses_insert on public.expenses for insert to authenticated with check (auth.uid() = user_id);
drop policy if exists expenses_update on public.expenses; create policy expenses_update on public.expenses for update to authenticated using (auth.uid() = user_id or public.get_my_role() in ('admin','gestor','financeiro')) with check (auth.uid() = user_id or public.get_my_role() in ('admin','gestor','financeiro'));
